fast_pseudocode:
# Do NOT do this — autotuning warps without tile sizes worsens register pressure
# Instead, autotune tile sizes as constexpr kernel args:
@triton.autotune(
    configs=[
        triton.Config({'BLOCK_M': 16, 'BLOCK_N': 32, 'BLOCK_K': 16}, num_warps=2),
        triton.Config({'BLOCK_M': 32, 'BLOCK_N': 32, 'BLOCK_K': 16}, num_warps=4),
        # ... vary BLOCK_M/BLOCK_N/BLOCK_K to reduce register pressure
    ],
    key=['M', 'N', 'K'],
)
@triton.jit
def kernel(A, B, out, M, N, K,
           BLOCK_M: tl.constexpr, BLOCK_N: tl.constexpr, BLOCK_K: tl.constexpr):
    # tile sizes now drive register allocation
